@WebServlet("/user")
public class UserServlet extends HttpServlet {
    private final Map<Integer, String> users = Map.of(1, "山田", 2, "佐藤");

    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws ServletException, IOException {
        String name = null;
        try {
            name = users.get(Integer.parseInt(req.getParameter("id")));
        } catch (RuntimeException ignored) { }
        if (name == null) {
            res.sendError(HttpServletResponse.SC_NOT_FOUND, "利用者が見つかりません");
            return;
        }
        req.setAttribute("userName", name);
        req.getRequestDispatcher("/user-view").forward(req, res);
    }

    public static void main(String[] args) {
        MiniWeb.app().register(UserServlet.class).register(UserView.class).serve();
    }
}

