import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;
import java.io.*;

@WebServlet("/account")
public class AccountServlet extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        HttpSession s = req.getSession(false);
        Object user = s == null ? null : s.getAttribute("loginUser");
        if (user == null) {
            res.sendError(HttpServletResponse.SC_UNAUTHORIZED, "ログインが必要です");
            return;
        }
        res.getWriter().println("利用者: " + user);
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String op = req.getParameter("op");
        if ("login".equals(op)) {
            String user = req.getParameter("user");
            if (user == null || user.isBlank()) {
                res.sendError(400, "userは必須です");
                return;
            }
            req.getSession().setAttribute("loginUser", user);
            res.getWriter().println("ログイン: " + user);
        } else if ("logout".equals(op)) {
            HttpSession s = req.getSession(false);
            if (s != null) s.invalidate();
            res.getWriter().println("ログアウトしました");
        } else res.sendError(400, "opが不正です");
    }

    public static void main(String[] args) {
        MiniWeb.app().register(AccountServlet.class).serve();
    }
}

