        String set = req.getParameter("set");
        if (set != null) {
            if (!set.equals("ja") && !set.equals("en")) {
                res.sendError(400, "langはjaまたはenです");
                return;
            }
            lang = set;
            Cookie c = new Cookie("lang", lang);
            c.setMaxAge(60 * 60 * 24 * 30);
            c.setPath("/");
            res.addCookie(c);
        }
        res.getWriter().println("lang=" + lang);
    }

    public static void main(String[] a) {
        MiniWeb.app().register(LangServlet.class).showCookies().serve();
