import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.*;
import java.io.*;

@WebServlet("/consent")
public class ConsentServlet extends HttpServlet {
    protected void doGet(HttpServletRequest req, HttpServletResponse res) throws IOException {
        String value = "none";
        Cookie[] cs = req.getCookies();
        if (cs != null) for (Cookie c : cs) if (c.getName().equals("consent")) value = c.getValue();
        if ("yes".equals(req.getParameter("accept"))) {
            Cookie c = new Cookie("consent", "yes");
            c.setPath("/");
            c.setHttpOnly(true);
            res.addCookie(c);
            value = "yes";
        }
        if ("yes".equals(req.getParameter("clear"))) {
            Cookie c = new Cookie("consent", "");
            c.setPath("/");
            c.setMaxAge(0);
            res.addCookie(c);
            value = "none";
        }
        res.getWriter().println("consent=" + value);
    }

    public static void main(String[] a) {
        MiniWeb.app().register(ConsentServlet.class).showCookies().serve();
    }
}

