@WebFilter("/admin/*")
class AuthFilter implements Filter {
    public void doFilter(HttpServletRequest q, HttpServletResponse s, FilterChain chain) throws ServletException, IOException {
        HttpSession session = q.getSession(false);
        if (session == null) {
            s.sendError(401, "ログインが必要です");
            return;
        }
        if (!"admin".equals(session.getAttribute("role"))) {
            s.sendError(403, "権限がありません");
            return;
        }
        chain.doFilter(q, s);
    }
}

